from pathlib import Path
program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # A row-wise pattern: each nonempty row is a single repeated color.
    row_values = {}
    row_mode = all(all(v == row[0] for v in row) for row in grid)
    if row_mode:
        row_values = {r: row[0] for r, row in enumerate(grid) if row[0] != 0}
        for period in range(1, h + 1):
            residues = {}
            ok = True
            for r, color in row_values.items():
                k = r % period
                if k in residues and residues[k] != color:
                    ok = False
                    break
                residues[k] = color
            if ok:
                return [[residues[r % period]] * w for r in range(h)]

    # Diagonal clues have a constant color along c-r. Repeat their smallest
    # compatible color sequence across all diagonals.
    diagonal_values = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                k = c - r
                if k in diagonal_values and diagonal_values[k] != color:
                    raise ValueError("conflicting colors on one diagonal")
                diagonal_values[k] = color
    max_period = max(h, w) + (max(h, w) - 1)
    for period in range(1, max_period + 1):
        residues = {}
        ok = True
        for d, color in diagonal_values.items():
            k = d % period
            if k in residues and residues[k] != color:
                ok = False
                break
            residues[k] = color
        if ok:
            return [[residues[(c-r) % period] for c in range(w)] for r in range(h)]
    raise ValueError("could not infer a periodic pattern")
'''
